// 4. Greek taxes — only bookings that are new, recent, or still missing tax
// data. Refetching all ~2000 every 15 minutes blew Hosthub's rate limit,
// which truncated the page fetches above and silently shrank the dataset.
const prevBkById = {};
(currentBksSync || []).forEach(b => { if (b && b.id != null) prevBkById[b.id] = b; });
const hasTaxData = b => !!(b && ((+b.ct || 0) || (+b.vat || 0) || (+b.at || 0) || (+b.bvPrevat || 0)));
const taxCutoff = new Date(Date.now() - 90 * 86400 * 1000).toISOString().slice(0, 10);
const needTax = bookingEvs.filter(ev => {
  const prev = prevBkById[ev.id];
  if (!prev || !hasTaxData(prev)) return true;
  return String(ev.date_to || '') >= taxCutoff;
});
needTax.sort((a, b) => String(b.date_to || '').localeCompare(String(a.date_to || '')));
const taxTargets = needTax.slice(0, 500);
log(`Fetching Greek taxes for ${taxTargets.length}/${bookingEvs.length} bookings (rest reuse stored values)…`);
const grTaxMap = {}; const BATCH_SIZE = 20; let fetched = 0;
for (let i = 0; i < taxTargets.length; i += BATCH_SIZE) {
  const chunk = taxTargets.slice(i, i + BATCH_SIZE);
  await Promise.all(chunk.map(async ev => {
    try {
      const r = await fetch(`${BASE}/calendar-events/${ev.id}/calendar-event-gr-taxes`, { headers: hhH(apiKey) });
      if (r.ok) grTaxMap[ev.id] = await r.json();
    } catch(e) {}
  }));
  fetched += chunk.length;
  if (fetched % 200 === 0 || fetched === taxTargets.length)
    log(`  Taxes: ${fetched}/${taxTargets.length} — ${Object.keys(grTaxMap).length} with data`);
}

patches.replace:
// 4. Greek taxes come from the booking_taxes store (filled by the tax worker,
// never by the sync). Every booking seen here is registered; rows without an
// answer are seeded from the values the app already holds, and anything else
// is flagged taxPending rather than written as 0.
const prevBkById = {};
(currentBksSync || []).forEach(b => { if (b && b.id != null) prevBkById[String(b.id)] = b; });
let grTaxMap = {}, taxPendingSet = new Set();
try {
  const reg = await taxStore.syncRegister(bookingEvs, prevBkById, log);
  grTaxMap = reg.map; taxPendingSet = reg.pending;
} catch (e) {
  log(`  Tax store unavailable (${e.message}) - reusing the values already in the app for this cycle`, 'warn');
  bookingEvs.forEach(ev => {
    const p = prevBkById[String(ev.id)];
    if (p && taxStore.hasData(p)) grTaxMap[String(ev.id)] = taxStore.seedFrom(p); else taxPendingSet.add(String(ev.id));
  });
}
log(`  Taxes: ${Object.keys(grTaxMap).length} from store, ${taxPendingSet.size} pending`, taxPendingSet.size ? 'warn' : 'ok');

