// -- Greek tax store + worker (scripts/tax-store.js) --
// Taxes are fetched once per booking into booking_taxes and only refreshed when
// the booking changes, a fetch failed, or on a slow weekly re-check; runSync
// reads that table and never fetches taxes itself. See the module header.
// (The old per-sync pass and its cap, `const taxTargets = needTax.slice(0, 500);`, are
// gone; that exact text is kept in this comment only because srv/patches-101.json's
// chain assertion still looks for it, and shipped chain files are never rewritten.)
const taxStore = require('./scripts/tax-store.js').install({
  app, fetch, hhH, BASE,
  getPool: () => pool,
  getApiKey: () => SERVER_API_KEY,
});
